def test_create_youtube_metadata():
    """Test creating YouTubeMetadata."""
    metadata = YouTubeMetadata(
        title="Test Video",
        description="Test description",
        tags=["torah", "hebrew"],
    )
    assert metadata.title == "Test Video"
    assert len(metadata.tags) == 2
    assert metadata.category_id == "27"


def test_metadata_title_too_long():
    """Test title length validation."""
    with pytest.raises(ValueError):
        YouTubeMetadata(
            title="x" * 101,
            description="Test",
        )


def test_metadata_tags_too_long():
    """Test tags total length validation."""
    with pytest.raises(ValueError, match="exceeds 500 chars"):
        YouTubeMetadata(
            title="Test",
            description="Test",
            tags=["x" * 501],
        )


def test_metadata_privacy_status_invalid():
    """Test invalid privacy status."""
    with pytest.raises(ValueError, match="Invalid privacy status"):
        YouTubeMetadata(
            title="Test",
            description="Test",
            privacy_status="invalid",
        )


def test_metadata_privacy_status_valid():
    """Test valid privacy statuses."""
    for status in ["private", "unlisted", "public"]:
        metadata = YouTubeMetadata(
            title="Test",
            description="Test",
            privacy_status=status,
        )
        assert metadata.privacy_status == status


# YouTubePlaylist tests

def test_create_youtube_playlist():
    """Test creating YouTubePlaylist."""
    playlist = YouTubePlaylist(
        playlist_id=1,
        youtube_playlist_id="PLxyz123",
        title="פרשת בראשית",
    )
    assert playlist.playlist_id == 1
    assert playlist.aliyah_count == 7


def test_playlist_is_complete_false():
    """Test is_complete when incomplete."""
    playlist = YouTubePlaylist(
        playlist_id=1,
        youtube_playlist_id="PLxyz123",
        title="Test",
        video_ids=["vid1", "vid2"],
    )
    assert not playlist.is_complete()


def test_playlist_is_complete_true():
    """Test is_complete when all videos present."""
    playlist = YouTubePlaylist(
        playlist_id=1,
        youtube_playlist_id="PLxyz123",
        title="Test",
        video_ids=[f"vid{i}" for i in range(7)],
    )
    assert playlist.is_complete()


def test_playlist_get_aliyah_position():
    """Test aliyah position mapping."""
    playlist = YouTubePlaylist(
        playlist_id=1,
        youtube_playlist_id="PLxyz123",
        title="Test",
    )

    assert playlist.get_aliyah_position("ראשון") == 0
    assert playlist.get_aliyah_position("שני") == 1
    assert playlist.get_aliyah_position("שלישי") == 2
    assert playlist.get_aliyah_position("unknown") == 0


