def test_create_youtube_upload():
    """Test creating YouTubeUpload."""
    upload = YouTubeUpload(
        id=1,
        alya_video_id=1,
        new_youtube_video_id="new123",
        uploaded_at=datetime.utcnow(),
    )
    assert upload.upload_status == "pending"


def test_upload_status_methods():
    """Test upload status helper methods."""
    pending = YouTubeUpload(
        id=1,
        alya_video_id=1,
        new_youtube_video_id="new123",
        upload_status="pending",
        uploaded_at=datetime.utcnow(),
    )
    assert pending.is_pending()
    assert not pending.is_completed()

    completed = YouTubeUpload(
        id=2,
        alya_video_id=1,
        new_youtube_video_id="new456",
        upload_status="completed",
        uploaded_at=datetime.utcnow(),
    )
    assert completed.is_completed()
    assert not pending.is_failed()

    failed = YouTubeUpload(
        id=3,
        alya_video_id=1,
        new_youtube_video_id="new789",
        upload_status="failed",
        error_message="Upload error",
        uploaded_at=datetime.utcnow(),
    )
    assert failed.is_failed()
